const clientes = $input.first().json.body?.clientes || [];

const recomendacoes = {
  "Conservador": "Tesouro Selic ou CDB Liquidez Diária (foco em segurança e liquidez)",
  "Moderado": "Tesouro IPCA+ ou CDB Prefixado (equilíbrio entre risco e proteção contra inflação)",
  "Arrojado": "Ações ETF ou Fundo de Ações (maior potencial de valorização a longo prazo)"
};

const resultados = clientes.map(c => {
  const rec = recomendacoes[c.perfil] || "Diversificação Geral";
  return {
    nome: c.nome,
    email: c.email,
    saldo: c.saldo,
    perfil: c.perfil,
    recomendacao: rec,
    mensagem: `Olá ${c.nome}! Com base no seu perfil ${c.perfil} e saldo de ${c.saldo}, sua recomendação personalizada é: ${rec}.`
  };
});

return [{ json: { status: "sucesso", total_clientes: resultados.length, clientes_processados: resultados } }];
